   157→        }
   158→
   159→        // Skip whitespace
   160→        if (is_space(c) == 1) {
   161→            i = i + 1;
   162→            continue;
   163→        }
   164→
   165→        // Number: 123
   166→        if (is_digit(c) == 1) {
