   168→            while (i < 10000 && is_digit(c) == 1) {
   169→                num = num * 10 + (c - 48);
   170→                i = i + 1;
   171→                c = 0;  // Would be input[i]
   172→            }
   173→            // Add token
   174→            tokens[count].type = TOK_INT;
   175→            tokens[count].value = num;
   176→            count = count + 1;
   177→            continue;
   178→        }
