content.text:
이제 FreeLang 컴파일러의 실제 C 출력 패턴을 완전히 파악했습니다. 상세 설계 계획을 작성하겠습니다.

---

# Mandate-DB 상세 구현 설계 계획

## 사전 분석: FreeLang 컴파일러 실제 제약사항

`compilation_run1.c`를 보면 컴파일러가 생성하는 C 코드 패턴이 명확합니다.

```c
// FL: var x: i64 = 0;   →  C: long x = 0;
// FL: fn foo() -> i64   →  C: long foo(void)
// FL: struct Foo { x: i64, }  →  C: typedef struct { long x; } Foo;
// FL: if (cond) { }     →  C: if ((cond)) { }
```

중요 제약:
- `extern fn printf(fmt: string) -> i32;` 패턴으로 C 라이브러리 호출 가능
- `*ASTNode` 처럼 포인터 타입 지원 (minicc.fl에서 확인)
- 배열: `var arr: [Token];` 선언 후 `arr[i].field = val;` 접근
- `let` (전역 상수) vs `var` (변수) 구분
- 문자열 비교는 `==` 연산자로 직접 (컴파일러가 strcmp로 변환)
- 재귀 함수 지원 (factorial.fl, fib.fl 확인)
- `println()`, `print()` 내장 함수 사용 가능

---

## 프로젝트 구조

```
/data/data/com.termux/files/home/projects/mandate-db/
├── src/
│   ├── types.fl              # 핵심 타입 정의
│   ├── storage.fl            # 불변 로그 저장소
│   ├── engine.fl             # 쿼리 엔진
│   ├── bulk_loader.fl        # 대량 데이터 삽입
│   ├── integrity_checker.fl  # SHA 해시 체인 무결성
│   ├── replication.fl        # 서버 간 복제
│   ├── failover.fl           # 장애 감지 & 복구
│   ├── time_travel.fl        # 시점 기반 쿼리
│   └── snapshot.fl           # 스냅샷 생성
├── tests/
│   ├── zero_validation_test.fl
│   ├── stress_test.fl
│   └── time_travel_test.fl
├── Makefile
└── README.md
```

---

## Phase 1: 코어 엔진

### `src/types.fl` - 기본 타입 정의

설계 근거: minicc.fl의 `Token`, `ASTNode` 구조체 패턴을 그대로 따릅니다. FreeLang 컴파일러는 중첩 구조체를 지원하므로 `MandateRecord`가 타임스탬프를 내장 필드로 보유하는 방식이 안전합니다.

```fl
// ============================================================
// types.fl - Mandate-DB 핵심 타입 정의
// ============================================================

// 작업 타입 상수 (불변)
let OP_SET: i64    = 1;   // 삽입/수정
let OP_DELETE: i64 = 2;   // 논리 삭제 (로그에 기록)
let OP_SCAN: i64   = 3;   // 범위 읽기
let OP_SNAP: i64   = 4;   // 스냅샷 명령

// 서버 상태 상수
let SRV_ALIVE: i64 = 1;
let SRV_DEAD: i64  = 0;

// 최대 크기 상수
let MAX_RECORDS: i64  = 10000;
let MAX_SERVERS: i64  = 2;
let KEY_SIZE: i64     = 64;
let HASH_SIZE: i64    = 32;

// -------------------------------------------------------
// MandateRecord: 불변 로그의 한 줄
// 모든 쓰기 작업은 이 구조체로 저장됨
// -------------------------------------------------------
struct MandateRecord {
    seq: i64,         // 시퀀스 번호 (단조 증가, 절대 중복 없음)
    timestamp: i64,   // 에폭 밀리초 (시뮬레이션용 정수)
    op: i64,          // 작업 타입: OP_SET, OP_DELETE
    key: string,      // 키 (최대 64자)
    value: string,    // 값 (OP_DELETE 시 빈 문자열)
    prev_hash: string, // 이전 레코드의 해시 (체인 연결)
    hash: string,     // 이 레코드의 해시 (SHA 시뮬레이션)
    server_id: i64,   // 어느 서버가 기록했는지 (253=서버A, 73=서버B)
    is_tombstone: i64, // 1 = 삭제 마커
}

// -------------------------------------------------------
// LogStore: 불변 로그 전체를 메모리에 보유
// -------------------------------------------------------
struct LogStore {
    records: [MandateRecord],
    count: i64,
    next_seq: i64,
    last_hash: string,    // 최신 레코드 해시 (체인 tail)
}

// -------------------------------------------------------
// ServerState: 각 서버(253/73)의 상태
// -------------------------------------------------------
struct ServerState {
    server_id: i64,
    status: i64,          // SRV_ALIVE / SRV_DEAD
    log: LogStore,
    last_sync_seq: i64,   // 마지막 동기화된 seq 번호
    pending_count: i64,   // 미동기화 레코드 수
}

// -------------------------------------------------------
// QueryResult: 쿼리 결과 래퍼
// -------------------------------------------------------
struct QueryResult {
    found: i64,       // 1 = 발견, 0 = 없음
    key: string,
    value: string,
    timestamp: i64,
    seq: i64,
}
```

**설계 결정사항:**
- `hash` 필드는 실제 SHA256 대신 `seq + key + value` 기반 정수 해시를 문자열로 저장 (extern 없이 구현 가능)
- `is_tombstone`을 별도 필드로 두어 OP_DELETE 레코드를 조회 시 필터링 용이
- `prev_hash`로 체인 구조를 형성 - 레코드 순서 위변조 탐지

---

### `src/storage.fl` - 불변 로그 저장소

설계 근거: FreeLang은 파일 I/O를 직접 지원하지 않으므로 `extern fn fopen/fwrite/fclose`를 선언하여 C stdlib를 활용합니다. ffi_complex.fl에서 `extern fn printf`가 작동하는 것이 확인되었습니다.

```fl
// ============================================================
// storage.fl - 불변 로그 저장소 (Append-Only)
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// 해시 계산 (경량 체인 해시)
// 실제 SHA256 없이 seq+key+value 조합으로 결정론적 해시 생성
// -------------------------------------------------------
fn compute_hash(seq: i64, key: string, value: string, prev_hash: string) -> string {
    // 결정론적 해시: seq를 기반으로 정수 생성
    // "H" + seq + "|" + key_length + "|" + value_length 형태
    var h: i64 = seq * 31;
    var i: i64 = 0;
    // key 문자 순회 (char_at 내장 함수 사용)
    var klen: i64 = length(key);
    while (i < klen) {
        var c: i64 = char_at(key, i);
        h = h * 31 + c;
        i = i + 1;
    }
    // value 문자 순회
    i = 0;
    var vlen: i64 = length(value);
    while (i < vlen) {
        var c: i64 = char_at(value, i);
        h = h * 17 + c;
        i = i + 1;
    }
    // 음수 방지
    if (h < 0) {
        h = h * -1;
    }
    return "H" + to_string(h);
}

// -------------------------------------------------------
// log_init: 저장소 초기화
// -------------------------------------------------------
fn log_init(store: *LogStore) -> i64 {
    store.count = 0;
    store.next_seq = 1;
    store.last_hash = "GENESIS";   // 최초 이전 해시 = GENESIS
    return 0;
}

// -------------------------------------------------------
// log_append: 새 레코드를 불변 로그에 추가
// 반환: 성공 시 seq 번호, 실패 시 -1
// -------------------------------------------------------
fn log_append(store: *LogStore, op: i64, key: string, value: string, server_id: i64) -> i64 {
    if (store.count >= MAX_RECORDS) {
        println("ERROR: LogStore full");
        return -1;
    }

    var idx: i64 = store.count;
    var seq: i64 = store.next_seq;

    // 레코드 채우기
    store.records[idx].seq = seq;
    store.records[idx].timestamp = seq * 1000;   // 시뮬레이션: seq당 1초
    store.records[idx].op = op;
    store.records[idx].key = key;
    store.records[idx].value = value;
    store.records[idx].server_id = server_id;
    store.records[idx].prev_hash = store.last_hash;

    // 삭제 마커 설정
    if (op == OP_DELETE) {
        store.records[idx].is_tombstone = 1;
        store.records[idx].value = "";
    } else {
        store.records[idx].is_tombstone = 0;
    }

    // 해시 계산 & 체인 연결
    var new_hash: string = compute_hash(seq, key, value, store.last_hash);
    store.records[idx].hash = new_hash;
    store.last_hash = new_hash;

    // 카운터 갱신
    store.count = store.count + 1;
    store.next_seq = store.next_seq + 1;

    return seq;
}

// -------------------------------------------------------
// log_get_by_seq: seq 번호로 레코드 조회
// -------------------------------------------------------
fn log_get_by_seq(store: *LogStore, seq: i64) -> i64 {
    var i: i64 = 0;
    while (i < store.count) {
        if (store.records[i].seq == seq) {
            return i;   // 인덱스 반환
        }
        i = i + 1;
    }
    return -1;
}

// -------------------------------------------------------
// log_print_record: 단일 레코드 출력 (디버깅용)
// -------------------------------------------------------
fn log_print_record(store: *LogStore, idx: i64) -> i64 {
    println("  seq=" + to_string(store.records[idx].seq)
        + " op=" + to_string(store.records[idx].op)
        + " key=" + store.records[idx].key
        + " val=" + store.records[idx].value
        + " hash=" + store.records[idx].hash);
    return 0;
}
```

**설계 결정사항:**
- `log_append`는 절대로 기존 레코드를 수정하지 않음 (불변성 보장)
- `compute_hash`는 `length()`, `char_at()` FreeLang 내장 함수만 사용 (extern 최소화)
- 타임스탬프는 `seq * 1000`으로 시뮬레이션 (실제 시스템은 extern gettimeofday 필요)
- `*LogStore` 포인터 매개변수로 구조체 수정 (minicc.fl의 `*ASTNode` 패턴 동일)

---

### `src/engine.fl` - 쿼리 엔진

```fl
// ============================================================
// engine.fl - Mandate-DB 쿼리 엔진
// GET, SET, DELETE, SCAN 4가지 연산 구현
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// engine_set: 키-값 쓰기 (불변 로그에 SET 명령 추가)
// -------------------------------------------------------
fn engine_set(store: *LogStore, key: string, value: string, server_id: i64) -> i64 {
    var seq: i64 = log_append(store, OP_SET, key, value, server_id);
    if (seq < 0) {
        return -1;
    }
    println("[SET] seq=" + to_string(seq) + " key=" + key + " value=" + value);
    return seq;
}

// -------------------------------------------------------
// engine_delete: 논리 삭제 (Tombstone 마커 삽입)
// 실제 데이터를 지우지 않음 - 삭제 명령을 기록
// -------------------------------------------------------
fn engine_delete(store: *LogStore, key: string, server_id: i64) -> i64 {
    var seq: i64 = log_append(store, OP_DELETE, key, "", server_id);
    println("[DELETE] seq=" + to_string(seq) + " key=" + key + " (tombstone)");
    return seq;
}

// -------------------------------------------------------
// engine_get: 최신 값 조회
// 로그를 역순으로 탐색 - 가장 최근 SET/DELETE 레코드 반환
// -------------------------------------------------------
fn engine_get(store: *LogStore, key: string) -> QueryResult {
    var result: QueryResult;
    result.found = 0;
    result.key = key;
    result.value = "";
    result.timestamp = 0;
    result.seq = -1;

    // 역순 탐색 (최신 레코드 우선)
    var i: i64 = store.count - 1;
    while (i >= 0) {
        if (store.records[i].key == key) {
            if (store.records[i].is_tombstone == 1) {
                // 삭제된 키 - 없음으로 반환
                result.found = 0;
                return result;
            }
            // 발견
            result.found = 1;
            result.value = store.records[i].value;
            result.timestamp = store.records[i].timestamp;
            result.seq = store.records[i].seq;
            return result;
        }
        i = i - 1;
    }
    return result;
}

// -------------------------------------------------------
// engine_scan: 키 접두사로 범위 조회
// prefix로 시작하는 모든 현재 유효한 키 출력
// -------------------------------------------------------
fn engine_scan(store: *LogStore, prefix: string) -> i64 {
    var count: i64 = 0;
    // 각 키의 최신 상태를 추적하는 배열 (단순 구현: 중복 키 마지막만)
    // 복잡한 해시맵 대신 두 번 순회 방식 사용
    var i: i64 = 0;
    println("[SCAN] prefix=" + prefix);

    while (i < store.count) {
        var rec_key: string = store.records[i].key;
        var plen: i64 = length(prefix);
        var klen: i64 = length(rec_key);

        // 접두사 매칭 확인
        var match: i64 = 1;
        if (klen < plen) {
            match = 0;
        }
        if (match == 1) {
            var j: i64 = 0;
            while (j < plen) {
                if (char_at(rec_key, j) != char_at(prefix, j)) {
                    match = 0;
                    j = plen;  // break 대신 조기 종료
                }
                j = j + 1;
            }
        }

        if (match == 1) {
            // 이 키의 최신 상태 확인
            var result: QueryResult = engine_get(store, rec_key);
            if (result.found == 1) {
                println("  key=" + rec_key + " value=" + result.value);
                count = count + 1;
            }
        }
        i = i + 1;
    }
    println("[SCAN] found=" + to_string(count) + " records");
    return count;
}

// -------------------------------------------------------
// main: 엔진 동작 검증 (smoke test)
// -------------------------------------------------------
fn main() -> i64 {
    var store: LogStore;
    log_init(&store);

    // 기본 SET/GET 테스트
    engine_set(&store, "user:1", "Alice", 253);
    engine_set(&store, "user:2", "Bob", 253);
    engine_set(&store, "user:1", "Alice_Updated", 253);

    var r: QueryResult = engine_get(&store, "user:1");
    if (r.found == 1) {
        println("GET user:1 = " + r.value);
    }

    // DELETE 테스트
    engine_delete(&store, "user:2", 253);
    var r2: QueryResult = engine_get(&store, "user:2");
    if (r2.found == 0) {
        println("GET user:2 = NOT FOUND (deleted correctly)");
    }

    // SCAN 테스트
    engine_scan(&store, "user:");

    return 0;
}
```

