## Phase 3: 서버 부하 분산 (253/73 시뮬레이션)

### `src/replication.fl` - 서버 간 복제 로직

설계 근거: 실제 소켓 통신은 FreeLang 제약상 어렵습니다. 대신 두 개의 `ServerState` 구조체를 메모리에 동시에 유지하고, 복제를 "서버 B의 LogStore에 서버 A의 pending 레코드를 append"하는 방식으로 시뮬레이션합니다. 이는 실제 분산 DB의 Raft 로그 복제와 논리적으로 동일합니다.

```fl
// ============================================================
// replication.fl - 253/73 서버 간 복제 로직
// 서버 253 = Primary, 서버 73 = Replica
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// ReplicationState: 복제 상태 추적
// -------------------------------------------------------
struct ReplicationState {
    primary: ServerState,    // 서버 253
    replica: ServerState,    // 서버 73
    sync_lag: i64,           // 복제 지연 (레코드 수)
    total_synced: i64,       // 누적 동기화 레코드 수
    sync_failures: i64,      // 동기화 실패 수
}

// -------------------------------------------------------
// repl_init: 복제 상태 초기화
// -------------------------------------------------------
fn repl_init(state: *ReplicationState) -> i64 {
    state.primary.server_id = 253;
    state.primary.status = SRV_ALIVE;
    log_init(&state.primary.log);
    state.primary.last_sync_seq = 0;
    state.primary.pending_count = 0;

    state.replica.server_id = 73;
    state.replica.status = SRV_ALIVE;
    log_init(&state.replica.log);
    state.replica.last_sync_seq = 0;
    state.replica.pending_count = 0;

    state.sync_lag = 0;
    state.total_synced = 0;
    state.sync_failures = 0;

    println("[REPL] Initialized: Primary=253, Replica=73");
    return 0;
}

// -------------------------------------------------------
// repl_write_primary: Primary에 쓰기 (비동기 복제 모델)
// 253에 즉시 쓰고, 73은 나중에 동기화
// -------------------------------------------------------
fn repl_write_primary(state: *ReplicationState, key: string, value: string) -> i64 {
    if (state.primary.status == SRV_DEAD) {
        println("[REPL] Primary 253 is DOWN - write rejected");
        return -1;
    }
    var seq: i64 = log_append(&state.primary.log, OP_SET, key, value, 253);
    state.primary.pending_count = state.primary.pending_count + 1;
    state.sync_lag = state.sync_lag + 1;
    return seq;
}

// -------------------------------------------------------
// repl_sync: Primary에서 Replica로 pending 레코드 복제
// last_sync_seq 이후 레코드를 순서대로 전달
// -------------------------------------------------------
fn repl_sync(state: *ReplicationState) -> i64 {
    if (state.replica.status == SRV_DEAD) {
        println("[REPL] Replica 73 is DOWN - sync skipped");
        state.sync_failures = state.sync_failures + 1;
        return 0;
    }

    var synced: i64 = 0;
    var last_seq: i64 = state.replica.last_sync_seq;

    var i: i64 = 0;
    while (i < state.primary.log.count) {
        var rec_seq: i64 = state.primary.log.records[i].seq;
        if (rec_seq > last_seq) {
            // 이 레코드를 Replica에 복제
            var key: string = state.primary.log.records[i].key;
            var value: string = state.primary.log.records[i].value;
            var op: i64 = state.primary.log.records[i].op;
            log_append(&state.replica.log, op, key, value, 73);
            state.replica.last_sync_seq = rec_seq;
            synced = synced + 1;
        }
        i = i + 1;
    }

    state.total_synced = state.total_synced + synced;
    state.sync_lag = state.sync_lag - synced;
    if (state.sync_lag < 0) {
        state.sync_lag = 0;
    }
    state.primary.pending_count = 0;

    println("[REPL] Synced " + to_string(synced) + " records to Replica 73"
        + " (lag=" + to_string(state.sync_lag) + ")");
    return synced;
}

// -------------------------------------------------------
// repl_status: 현재 복제 상태 출력
// -------------------------------------------------------
fn repl_status(state: *ReplicationState) -> i64 {
    println("=== Replication Status ===");
    println("  Primary 253: status="
        + to_string(state.primary.status)
        + " records=" + to_string(state.primary.log.count));
    println("  Replica  73: status="
        + to_string(state.replica.status)
        + " records=" + to_string(state.replica.log.count));
    println("  Sync lag    : " + to_string(state.sync_lag));
    println("  Total synced: " + to_string(state.total_synced));
    println("  Sync failures: " + to_string(state.sync_failures));
    return 0;
}
```

