extern fn printf(fmt: string) -> i32;

fn test_stress() -> i64 {
    println("=== Stress Test: Server 253/73 ===");

    var state: ReplicationState;
    repl_init(&state);

    // Phase A: 정상 쓰기 100개
    println("--- Phase A: Normal writes ---");
