        var key: string = "stress:key:" + to_string(i);
        var value: string = "val_" + to_string(i * 3);
        repl_write_primary(&state, key, value);
        i = i + 1;
    }
    repl_sync(&state);
    repl_status(&state);

    // Phase B: Primary 장애 시뮬레이션
