    var data_ok: i64 = verify_no_data_loss(&state, "stress:key:50");

    // Phase D: 복구
    println("--- Phase D: Server Recovery ---");
    var recovered: i64 = recover_server(&state);

    // Phase E: 최종 상태
    repl_status(&state);

    if (data_ok == 1) {
        println("STRESS TEST: PASS - No data loss during failover");
        return 0;
    }
    println("STRESS TEST: FAIL");
    return 1;
}

fn main() -> i64 {
    return test_stress();
}
