### `src/snapshot.fl` - 스냅샷 생성

```fl
// ============================================================
// snapshot.fl - 특정 시점의 완전한 상태 스냅샷
// 타임 트래블 쿼리를 모든 키에 적용하여 상태 재현
// ============================================================

extern fn printf(fmt: string) -> i32;

// -------------------------------------------------------
// SnapshotEntry: 스냅샷의 단일 키-값 쌍
// -------------------------------------------------------
struct SnapshotEntry {
    key: string,
    value: string,
    last_seq: i64,
    last_ts: i64,
}

// -------------------------------------------------------
// Snapshot: 특정 시점의 전체 상태
// -------------------------------------------------------
struct Snapshot {
    timestamp: i64,
    entries: [SnapshotEntry],
    count: i64,
}

// -------------------------------------------------------
// snapshot_create: target_ts 시점의 완전한 스냅샷 생성
// 로직: 모든 고유 키에 대해 tt_get_at 호출
// -------------------------------------------------------
fn snapshot_create(store: *LogStore, snap: *Snapshot, target_ts: i64) -> i64 {
    snap.timestamp = target_ts;
    snap.count = 0;

    println("[SNAPSHOT] Creating snapshot at ts=" + to_string(target_ts));

    // 고유 키 목록 수집 (정렬 없이 순서대로)
    var seen_keys: [string];
    var seen_count: i64 = 0;

    var i: i64 = 0;
    while (i < store.count) {
        if (store.records[i].timestamp > target_ts) {
            i = i + 1;
            continue;
        }

        var key: string = store.records[i].key;
        // 이미 처리한 키인지 확인
        var already_seen: i64 = 0;
        var j: i64 = 0;
        while (j < seen_count) {
            if (seen_keys[j] == key) {
                already_seen = 1;
                j = seen_count;   // break
            }
            j = j + 1;
        }

        if (already_seen == 0) {
            seen_keys[seen_count] = key;
            seen_count = seen_count + 1;

            // 이 시점에서의 값 조회
            var result: QueryResult = tt_get_at(store, key, target_ts);
            if (result.found == 1) {
                snap.entries[snap.count].key = key;
                snap.entries[snap.count].value = result.value;
                snap.entries[snap.count].last_seq = result.seq;
                snap.entries[snap.count].last_ts = result.timestamp;
                snap.count = snap.count + 1;
            }
        }
        i = i + 1;
    }

    println("[SNAPSHOT] Created: " + to_string(snap.count) + " entries at ts="
        + to_string(target_ts));
    return snap.count;
}

// -------------------------------------------------------
// snapshot_print: 스냅샷 출력
// -------------------------------------------------------
fn snapshot_print(snap: *Snapshot) -> i64 {
    println("=== Snapshot at ts=" + to_string(snap.timestamp) + " ===");
    var i: i64 = 0;
    while (i < snap.count) {
        println("  " + snap.entries[i].key + " = " + snap.entries[i].value
            + " (seq=" + to_string(snap.entries[i].last_seq) + ")");
        i = i + 1;
    }
    println("  Total: " + to_string(snap.count) + " entries");
    return snap.count;
}

// -------------------------------------------------------
// snapshot_compare: 두 스냅샷 비교 (변경된 키 수 반환)
// -------------------------------------------------------
fn snapshot_compare(snap_a: *Snapshot, snap_b: *Snapshot) -> i64 {
    println("[SNAPSHOT] Comparing ts=" + to_string(snap_a.timestamp)
        + " vs ts=" + to_string(snap_b.timestamp));
    var diff_count: i64 = 0;

    var i: i64 = 0;
    while (i < snap_b.count) {
        var key: string = snap_b.entries[i].key;
        var val_b: string = snap_b.entries[i].value;

        // snap_a에서 동일 키 찾기
        var found_in_a: i64 = 0;
        var j: i64 = 0;
        while (j < snap_a.count) {
            if (snap_a.entries[j].key == key) {
                found_in_a = 1;
                if (snap_a.entries[j].value != val_b) {
                    println("  CHANGED: " + key
                        + " [" + snap_a.entries[j].value + " -> " + val_b + "]");
                    diff_count = diff_count + 1;
                }
                j = snap_a.count;  // break
            }
            j = j + 1;
        }

        if (found_in_a == 0) {
            println("  ADDED: " + key + " = " + val_b);
            diff_count = diff_count + 1;
        }
        i = i + 1;
    }
    println("  Total diffs: " + to_string(diff_count));
    return diff_count;
}
```

