### `tests/time_travel_test.fl` - 타임 트래블 테스트

```fl
// ============================================================
// time_travel_test.fl - 타임 트래블 & 스냅샷 테스트
// ============================================================

extern fn printf(fmt: string) -> i32;

fn test_time_travel() -> i64 {
    println("=== Time Travel Test ===");

    var store: LogStore;
    log_init(&store);

    // 히스토리 구축
    // ts=1000: user:1 = Alice
    log_append(&store, OP_SET, "user:1", "Alice", 253);     // seq=1, ts=1000
    // ts=2000: user:2 = Bob
    log_append(&store, OP_SET, "user:2", "Bob", 253);       // seq=2, ts=2000
    // ts=3000: user:1 = Alice_V2
    log_append(&store, OP_SET, "user:1", "Alice_V2", 253);  // seq=3, ts=3000
    // ts=4000: user:3 = Charlie
    log_append(&store, OP_SET, "user:3", "Charlie", 253);   // seq=4, ts=4000
    // ts=5000: user:2 삭제
    log_append(&store, OP_DELETE, "user:2", "", 253);        // seq=5, ts=5000
    // ts=6000: user:1 = Alice_V3
    log_append(&store, OP_SET, "user:1", "Alice_V3", 253);  // seq=6, ts=6000

    println("Log built: " + to_string(store.count) + " records");

    // 타임 트래블 테스트 1: ts=1500 시점 (user:2 존재 전)
    println("--- Test 1: tt_get_at ts=1500 ---");
    var r1: QueryResult = tt_get_at(&store, "user:2", 1500);
    if (r1.found == 0) {
        println("  PASS: user:2 not found at ts=1500 (not yet inserted)");
    } else {
        println("  FAIL: user:2 should not exist at ts=1500");
        return 1;
    }

    // 타임 트래블 테스트 2: ts=2500 시점 (user:1 = Alice, user:2 = Bob)
    println("--- Test 2: tt_get_at ts=2500 ---");
    var r2: QueryResult = tt_get_at(&store, "user:1", 2500);
    if (r2.found == 1 && r2.value == "Alice") {
        println("  PASS: user:1 = Alice at ts=2500");
    } else {
        println("  FAIL: user:1 should be Alice at ts=2500, got=" + r2.value);
        return 1;
    }

    // 타임 트래블 테스트 3: ts=5500 시점 (user:2 삭제 후)
    println("--- Test 3: tt_get_at ts=5500 ---");
    var r3: QueryResult = tt_get_at(&store, "user:2", 5500);
    if (r3.found == 0) {
        println("  PASS: user:2 deleted at ts=5500");
    } else {
        println("  FAIL: user:2 should be deleted at ts=5500");
        return 1;
    }

    // 타임 트래블 테스트 4: ts=3500 시점 스캔
    println("--- Test 4: tt_scan_at ts=3500 ---");
    var scan_count: i64 = tt_scan_at(&store, "user:", 3500);
    // 이 시점: user:1=Alice_V2, user:2=Bob (user:3 아직 없음)
    if (scan_count == 2) {
        println("  PASS: 2 users at ts=3500");
    } else {
        println("  FAIL: expected 2 users, got " + to_string(scan_count));
        return 1;
    }

    // 스냅샷 테스트: ts=3000 vs ts=6000 비교
    println("--- Test 5: Snapshot comparison ---");
    var snap_early: Snapshot;
    var snap_late: Snapshot;
    snapshot_create(&store, &snap_early, 3000);
    snapshot_create(&store, &snap_late, 6000);
    snapshot_print(&snap_early);
    snapshot_print(&snap_late);
    var diffs: i64 = snapshot_compare(&snap_early, &snap_late);
    if (diffs > 0) {
        println("  PASS: " + to_string(diffs) + " changes detected between snapshots");
    }

    // DIFF 테스트
    println("--- Test 6: tt_diff ---");
    var changes: i64 = tt_diff(&store, 2000, 5000);
    // 기간 내 변경: seq3(user:1 update), seq4(user:3 add), seq5(user:2 delete) = 3개
    if (changes == 3) {
        println("  PASS: 3 changes detected in ts 2000-5000");
    } else {
        println("  Result: " + to_string(changes) + " changes");
    }

    println("TIME TRAVEL TEST: PASS");
    return 0;
}

fn main() -> i64 {
    return test_time_travel();
}
```

